/**
 * @description
 * 本脚本用于 n8n 的 "Code" 节点。
 * 功能：接收一个包含文章信息的 JSON 字符串，将其转换为 Hugo 静态网站生成器所需的 Markdown 文件格式。
 *
 * 输入：上一个节点传递过来的数据项，其中应包含一个名为 `content` 的字段，
 * 该字段的值是一个 JSON 格式的字符串。
 *
 * 输出：一个包含两部分的新对象：
 * 1. `hugoArticle`: 格式化后的完整 Hugo 文章字符串。
 * 2. `fileName`: 根据文章标题建议的文件名。
 */

// --- 1. 数据准备 ---

const rawContentString = $json.content;

if (!rawContentString || typeof rawContentString !== 'string') {
  throw new Error("输入字段 'content' 为空或不是字符串，无法继续。");
}

// --- 2. 最终版：健壮的 JSON 解析 ---

let articleData;
let jsonString = ''; // 用于存放提取出的、待解析的字符串

try {
  // 第1步：优先尝试从 Markdown 代码块 (```json ... ```) 中提取核心内容。
  const markdownMatch = rawContentString.match(/```json\s*([\s\S]*?)\s*```/);

  if (markdownMatch && markdownMatch[1]) {
    jsonString = markdownMatch[1];
  } else {
    // 第2步：[智能后备方案] 如果没找到Markdown块，就从字符串中找到第一个'{'和最后一个'}'来提取JSON。
    // 这能处理LLM在JSON前后添加了额外文本的情况。
    const firstBrace = rawContentString.indexOf('{');
    const lastBrace = rawContentString.lastIndexOf('}');

    if (firstBrace > -1 && lastBrace > firstBrace) {
      jsonString = rawContentString.substring(firstBrace, lastBrace + 1);
    } else {
      // 如果连大括号都找不到，说明输入内容完全不是JSON。
      throw new Error("在输入内容中找不到有效的JSON对象结构。");
    }
  }

  // 第3步：对提取出的核心JSON字符串进行深度清理
  // a. 将合法的、已转义的换行符 \\n 替换为临时占位符，保护它们不被误删。
  jsonString = jsonString.replace(/\\n/g, '__TEMP_NEWLINE__');
  // b. 将所有非法的、用于格式化的物理换行符 \n 替换为空格。
  jsonString = jsonString.replace(/\n/g, ' ');
  // c. 将占位符恢复为合法的转义换行符 \\n。
  jsonString = jsonString.replace(/__TEMP_NEWLINE__/g, '\\n');

  // d. 移除尾随逗号。
  jsonString = jsonString.replace(/,\s*([}\]])/g, '$1');

  // 第4步：循环解析，处理“双重编码”问题。
  let parsedResult = JSON.parse(jsonString);
  for (let i = 0; i < 5 && typeof parsedResult === 'string'; i++) {
    let innerString = parsedResult.replace(/,\s*([}\]])/g, '$1');
    parsedResult = JSON.parse(innerString);
  }

  if (typeof parsedResult !== 'object' || parsedResult === null) {
      throw new Error("解析后的最终结果不是一个有效的 JSON 对象。");
  }

  articleData = parsedResult;

} catch (e) {
  console.error("解析 'content' 字段中的 JSON 字符串失败:", e);
  throw new Error(`JSON 解析失败: ${e.message}. 尝试解析的内容是: "${jsonString}"`);
}

// --- 3. 提取并验证内容 ---

const {
  title,
  summary,
  tags,
  main_topics,
  article_content
} = articleData;

if (!title || !article_content) {
  throw new Error("解析后的数据缺少必要的 'title' 或 'article_content' 字段。");
}

// --- 4. 构建 Hugo Front Matter (YAML 格式) ---

const getISODateWithTimezone = (date) => {
    const pad = (num) => (num < 10 ? '0' : '') + num;
    const offset = -date.getTimezoneOffset();
    const sign = offset >= 0 ? '+' : '-';
    const hours = pad(Math.floor(Math.abs(offset) / 60));
    const minutes = pad(Math.abs(offset) % 60);
    return `${date.getFullYear()}-${pad(date.getMonth() + 1)}-${pad(date.getDate())}T${pad(date.getHours())}:${pad(date.getMinutes())}:${pad(date.getSeconds())}${sign}${hours}:${minutes}`;
};
const hugoDate = getISODateWithTimezone(new Date());

const toYamlString = (value) => JSON.stringify(value);

const toYamlList = (arr) => {
    if (!Array.isArray(arr)) return '';
    return arr.map(item => `  - ${toYamlString(item)}`).join('\n');
}

const frontMatter = `---
title: ${toYamlString(title)}
date: ${hugoDate}
draft: false
summary: ${toYamlString(summary || '')}
tags:
${toYamlList(tags || [])}
main_topics:
${toYamlList(main_topics || [])}
---
`;

// --- 5. 组合并返回最终结果 ---

// 将解析时替换的\\n恢复为真实的换行符，以便在Markdown中正确显示段落
const finalArticleContent = article_content.replace(/\\n/g, '\n');

const hugoArticle = frontMatter + '\n' + finalArticleContent;

const generateSlug = (str) =>
  str
    .toString()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .toLowerCase()
    .trim()
    .replace(/\s+/g, '-')
    .replace(/[^\w-]+/g, '')
    .replace(/--+/g, '-');

return {
  json: {
    hugo_article: hugoArticle,
    fileName: `${generateSlug(title)}.md`
  }
};

/**
 * 检查文件写入是否成功
 * 通过检查Execute Command节点的执行结果判断
 */
function checkWriteSuccess() {
  const writeResult = $json;

  // Execute Command节点成功时会返回执行信息
  const success = writeResult && (writeResult.exitCode === 0 || writeResult.exitCode === undefined);

  return {
    success: success,
    fileName: $('生成Hugo内容').item.json.fileName,
    articleId: $('生成Hugo内容').item.json.articleId,
    title: $('生成Hugo内容').item.json.title,
    filePath: `/app/hugo/hugo/content/articles/${$('生成Hugo内容').item.json.fileName}`,
    error: success ? null : '文件写入失败',
    exitCode: writeResult.exitCode || 0
  };
}

return checkWriteSuccess();

/**
 * 更新单篇文章的同步状态
 * 为每篇成功同步的文章更新状态
 */
function updateSyncStatus() {
  const data = $json;

  return {
    articleId: $('生成Hugo内容').item.json.articleId,
    title: $('生成Hugo内容').item.json.title,
    fileName: $('生成Hugo内容').item.json.fileName,
    syncTime: new Date().toISOString(),
    status: 'synced_to_hugo'
  };
}

return updateSyncStatus();

/**
 * 记录同步失败的文章
 * 用于错误处理和日志记录
 */
function logSyncFailure() {
  const data = $json;

  return {
    articleId: data.articleId || $('生成Hugo内容').item.json.articleId,
    title: data.title || $('生成Hugo内容').item.json.title,
    error: data.error || data.message || '未知错误',
    timestamp: new Date().toISOString(),
    status: 'sync_failed'
  };
}

return logSyncFailure();
